(function(){
  'use strict';
  const C=window.MakerContent,E=window.MakerEngine,M=window.MakerMedia,A=window.MakerAppearance,G=window.MakerClassic;
  const app=document.getElementById('app'),modal=document.getElementById('modal'),toastElement=document.getElementById('toast');
  const PREFIX='starlight-life/v1/',AUTO='autosave',KEYS=Object.keys(C.STATS);
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number=value=>new Intl.NumberFormat('ko-KR').format(value);
  const signed=value=>(value>0?'+':'')+value;
  let game=null,plan=[null,null,null,null],view='home',chartStat='intellect',journalLimit=12,pickerWeek=0,pickerCategory='study',shopPane='catalog',shopCategory='all',selectedOutfit='auto',wardrobeRoomOnly=false,toastTimer=null,saveOK=true;
  function toast(message,error=false){clearTimeout(toastTimer);toastElement.textContent=message;toastElement.className='toast visible'+(error?' error':'');toastTimer=setTimeout(()=>toastElement.classList.remove('visible'),4500)}
  function read(key){try{return localStorage.getItem(PREFIX+key)}catch{return null}}
  function write(key,value){try{localStorage.setItem(PREFIX+key,value);return true}catch{toast('이 브라우저에 저장할 수 없어요. 저장함에서 파일로 내보내 주세요.',true);return false}}
  function payload(){const data=JSON.parse(E.serialize(game));data.draftPlan=[...plan];data.outfit=selectedOutfit;return JSON.stringify(data,null,2)}
  function persist(){if(!game)return;saveOK=write(AUTO,payload());rememberEnding()}
  function collection(){try{const value=JSON.parse(read('endings')||'[]');return Array.isArray(value)?value.filter(id=>E.endings[id]):[]}catch{return []}}
  function rememberEnding(){if(!game?.endingId)return;const ids=collection();if(!ids.includes(game.endingId))write('endings',JSON.stringify([...ids,game.endingId]))}
  function decode(raw){
    const next=E.deserialize(raw),envelope=JSON.parse(raw),draft=envelope.draftPlan;
    return {game:next,plan:Array.isArray(draft)&&draft.length===4?draft.map(id=>id&&E.activities[id]&&!E.requirement(next,id)?id:null):[null,null,null,null],outfit:A.normalize(M,next.characterId,E.date(next).age,envelope.outfit)};
}
  function load(raw){const next=decode(raw);game=next.game;selectedOutfit=next.outfit;plan=game.phase==='planning'?next.plan:[null,null,null,null];view='home';journalLimit=12;modal.close();persist();render();if(game.phase==='event')showEvent();else if(game.phase==='ending')showEnding()}
  function saveInfo(raw){if(!raw)return null;try{const state=E.deserialize(raw),d=E.date(state);return {name:state.childName,age:d.age,date:d.year+'년 '+d.month+'월',ending:state.phase==='ending'}}catch{return {invalid:true}}}
  function header(landing=false){return `<header class="topbar"><div class="brand"><span class="star" aria-hidden="true">✧</span><div><span class="brand-name">별이 자라는 집</span><span class="brand-sub">A LITTLE LIFE, A NEW SEASON</span></div></div><div class="top-actions">${landing?`<button class="button ghost" data-action="saves">저장함</button><button class="button ghost" data-action="help">놀이 방법</button>`:`<div class="gold"><strong>${number(game.gold)} <span>G</span></strong><small>소지금</small></div><button class="button ghost help-top" data-action="help">도움말</button><button class="button" data-action="saves">저장함</button><button class="button ghost new-top" data-action="new">새 이야기</button>`}<button class="button ghost install-button" data-pwa-action="install"><span class="install-label-long">홈 화면에 설치</span><span class="install-label-short">설치</span></button></div></header>`}
  function landing(){const saved=saveInfo(read(AUTO));app.innerHTML=`<div class="landing title-screen">${header(true)}<main class="title-content"><div class="title-portraits" aria-hidden="true"><img class="book-character-image" src="${mediaURL(M.portraits.ciel[10].base)}" alt=""><img class="book-character-image" src="${mediaURL(M.portraits.valeria[10].base)}" alt=""></div><section class="title-main"><p class="title-ornament">✧ ───── ✦ ───── ✧</p><p class="title-kicker">당신과 함께하는 여덟 번의 봄</p><h1>별이 자라는 집</h1><p class="title-subtitle">육성 이야기</p><div class="title-menu"><button class="button primary" data-action="continue" ${!saved||saved.invalid?'disabled':''}>이야기 이어가기</button><button class="button" data-action="new">새로운 이야기 시작</button><button class="button" data-action="collection">추억의 앨범</button></div><p class="title-save">${saved&&!saved.invalid?esc(saved.name)+' · '+saved.age+'세 · '+saved.date:'열 살의 봄, 우리의 이야기가 시작됩니다.'}</p><p class="title-ornament">✧ ───── ✦ ───── ✧</p></section></main></div>`}
  function mediaURL(path){return typeof path==='string'&&path?M.basePath+path:''}
  function portrait(large=false){
    const d=E.date(game),season=E.season(game),look=A.resolve(M,{characterId:game.characterId,originId:game.originId,age:d.age,season},selectedOutfit),painting=mediaURL(window.MakerScenes?.paintings?.[game.originId]||M.painting);
    return `<div class="portrait has-art ${large?'portrait-large':''} ${large&&wardrobeRoomOnly?'room-only':''}" aria-label="${esc(game.childName)}의 방과 ${look.label}"><img class="room-image" data-media="room" src="${look.roomSource}" alt="${C.ORIGINS[game.originId].room}" decoding="async">${painting?`<img class="painting" data-media="painting" src="${esc(painting)}" alt="방의 액자 그림">`:''}<span class="portrait-season">${season} · ${d.age}세</span><div class="portrait-placeholder" hidden><span class="letter" aria-hidden="true">${C.CHARACTERS[game.characterId].initial}</span><span class="label">그림을 불러오지 못했어요</span><span class="portrait-note">인터넷에 연결한 뒤 다시 열어 주세요.</span></div><img class="child-image" data-media="child" data-fallback="${look.fallbackSource}" src="${look.source}" alt="${look.age}세 ${esc(game.childName)} · ${look.label}" decoding="async"><span class="scene-caption"><span>${look.label}</span></span></div>`;
}
  function meter(key,label,style=''){return `<div class="meter-row"><span class="meter-label">${label}</span><div class="meter-track" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${game[key]}"><span class="meter-fill ${style}" style="width:${game[key]}%"></span></div><span class="meter-number">${game[key]}</span></div>`}
  function weekCards(){return `<div class="week-grid">${plan.map((id,index)=>{const a=E.activities[id];return `<button class="week-card ${a?'':'empty'}" data-action="pick-week" data-week="${index}" aria-label="${index+1}주차 ${a?a.name:'일정 선택'}" ${game.phase!=='planning'?'disabled':''}><span class="week-label">${index+1}주차</span><span class="activity-mark" aria-hidden="true">${a?a.mark:'+'}</span><span class="week-name">${a?a.name:'일정 정하기'}</span><span class="week-cost ${a?.cost?'cost':a?.income?'income':''}">${a?a.cost?`−${a.cost}G`:a.income?`+${E.workIncome(game,a)}G`:'비용 없음':'작은 하루의 시작'}</span></button>`}).join('')}</div>`}
  function planner(){
    const f=E.forecast(game,plan),ready=f.complete&&game.phase==='planning',poss=E.possibilities(game).find(e=>e.id===game.dreamId),work=E.workStatus(game),recent=game.journal.slice(0,2),warnings=[];
    if(f.unaffordableWeeks.length)warnings.push(`${f.unaffordableWeeks.join('·')}주차 비용이 부족해요. 해당 주는 집에서 쉬게 됩니다. 쉬는 일정을 반영하면 ${number(f.goldAfterFallback)}G가 남아요.`);
    if(f.recoveryWeeks.length)warnings.push(`${f.recoveryWeeks.join('·')}주차는 컨디션이 낮아 회복 일정으로 바뀔 수 있어요.`);
    if(f.peakFatigue>85)warnings.push('주중에 피로가 크게 쌓일 수 있어요. 힘든 활동 앞에 휴식을 배치해 보세요.');
    return `<section class="panel"><div class="planner-heading"><div><h2 class="panel-title">이번 달의 일정</h2><p class="panel-sub">교육 · 아르바이트 · 휴식 · 무사수행</p></div><div class="planner-shortcuts"><button class="button small-button" data-action="recommend" ${game.phase!=='planning'?'disabled':''}>추천 일정</button><button class="button ghost small-button" data-action="repeat" ${!game.lastPlan.length||game.phase!=='planning'?'disabled':''}>지난달처럼</button></div></div>${weekCards()}<div class="planner-budget"><div class="budget-numbers"><span>활동 지출<strong>−${f.cost}G</strong></span><span>예상 수입<strong>+${f.income}G</strong></span><span>월 지원금<strong>+${f.allowance}G</strong></span><span>생활비<strong>−${f.livingCost}G</strong></span></div><div class="budget-final ${f.gold<0?'short':''}"><span>${f.gold<0?'추가로 필요한 돈':'예상 남는 돈'}</span><strong>${number(Math.abs(f.gold))} G</strong></div></div><p class="budget-note">${f.starterGrant?'처음 세 달은 정착 지원 15G가 월 지원금에 포함돼요. ':''}생활비는 매달 먼저 사용해요. 탐험에서 발견하는 돈은 예상 수입에 포함하지 않아요.</p>${game.shop?.equippedToolId?`<p class="active-tool-note">준비 도구 · ${esc(E.shopInfo(game).equippedTool.name)}<br>${esc(E.itemUsePreview(game,game.shop.equippedToolId).detail)}</p>`:''}<p class="work-note">일손 경험 · ${work.label}${work.next?` · ${work.next-work.weeks}주 더 일하면 주급이 올라요`:' · 숙련 주급을 받아요'}<br>주급은 경험과 몸 상태에 따라 달라집니다.</p>${warnings.map(w=>`<p class="planner-warning">${w}</p>`).join('')}<div class="planner-footer"><p class="auto-save-note">${saveOK?'이야기는 자동으로 저장됩니다.':'저장이 어려워요. 저장함에서 파일로 보관해 주세요.'}<br>${game.elapsed} / 96개월의 추억</p><button id="advance-button" class="button primary" data-action="advance" ${ready?'':'disabled'}>${game.phase==='ending'?'이야기가 완성되었어요':f.complete?'한 달 보내기 →':'4주 일정을 정해 주세요'}</button></div></section>${festivalTeaser()}<div class="below-panels"><section class="panel goal-preview"><div style="flex:1"><p class="eyebrow">A LITTLE DREAM</p><h3>${poss.title}</h3><p class="small muted">${poss.short}</p><div class="progress"><span style="width:${poss.progress*100}%"></span></div></div><div class="goal-progress-text">${Math.round(poss.progress*100)}%<small>가능성의 준비</small><button class="link-button" data-action="view" data-view="dreams">진로 살펴보기</button></div></section><section class="panel"><div class="row spread"><h2 class="panel-title">최근의 이야기</h2><button class="link-button" data-action="view" data-view="journal">일지 펼치기</button></div>${recent.map(entry=>`<article class="recent-entry"><h3>${esc(entry.title)}</h3><p>${esc(entry.body)}</p></article>`).join('')}</section></div>`;
}
  function chart(){const history=game.history,values=history.map(s=>s.stats[chartStat]),max=Math.max(100,Math.ceil(Math.max(...values)/100)*100);const x=m=>45+m/96*540,y=value=>170-value/max*135;const points=history.map(s=>`${x(s.month)},${y(s.stats[chartStat])}`).join(' ');return `<svg class="growth-chart" viewBox="0 0 610 210" role="img" aria-label="${C.STATS[chartStat].name} 성장 기록. 현재 ${game.stats[chartStat]}">${[0,.5,1].map(f=>`<line x1="45" x2="585" y1="${y(max*f)}" y2="${y(max*f)}" stroke="#e4e8d9"/><text class="chart-axis" x="32" y="${y(max*f)+4}" text-anchor="end">${Math.round(max*f)}</text>`).join('')}${[0,24,48,72,96].map(m=>`<text class="chart-axis" x="${x(m)}" y="198" text-anchor="middle">${10+m/12}세</text>`).join('')}<polyline points="${points}" fill="none" stroke="${C.STATS[chartStat].color}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(game.elapsed)}" cy="${y(game.stats[chartStat])}" r="4" fill="${C.STATS[chartStat].color}"/></svg>`}
  function journalView(){
    const story=E.characterStory(game),memories=[...story.memories].reverse();
    const nextAge=story.next?10+Math.floor((story.next.minMonth-1)/12):null;
    return `<section class="panel"><div class="row spread"><div><h2 class="panel-title">조금씩, 멀리 자라고 있어요</h2><p class="panel-sub">열 살의 봄부터 쌓아 온 성장의 흔적입니다.</p></div><select id="chart-stat" class="chart-select" aria-label="성장 기록 능력치">${KEYS.map(key=>`<option value="${key}" ${chartStat===key?'selected':''}>${C.STATS[key].name}</option>`).join('')}</select></div>${chart()}${game.elapsed===0?'<p class="small muted">한 달을 보내면 새로운 기록이 더해집니다.</p>':''}</section><section class="panel story-panel"><div class="row spread"><div><h2 class="panel-title">${esc(game.childName)}의 성장 에피소드</h2><p class="panel-sub">함께 고른 장면과 아이의 답변을 모았어요.</p></div><span class="story-count">${story.completed} / ${story.total}</span></div>${memories.length?memories.map(m=>{const d=E.date({elapsed:m.month-1});return `<details class="story-memory" ${m===memories[0]?'open':''}><summary><span class="story-memory-date">${d.age}세 · ${d.year}년 ${d.month}월 · ${m.chapter}</span><strong>${m.episode}. ${esc(m.title)}</strong></summary><p class="story-choice">${esc(m.label)}</p><blockquote>“${esc(m.reaction)}”<cite>— ${esc(game.childName)}</cite></blockquote></details>`}).join(''):'<p class="empty-note">아직 펼치지 않은 첫 장이 기다리고 있어요.<br>한 달씩 함께 지내다 보면 아이만의 이야기가 찾아옵니다.</p>'}${story.next&&game.phase!=='ending'?`<p class="story-next">다음 장 · ${esc(story.next.chapter)}${E.date(game).age<nextAge?` · ${nextAge}세 이후에 이어져요`:' · 일상 속에서 천천히 이어져요'}</p>`:''}</section><section class="panel" style="margin-top:18px"><div class="row spread"><h2 class="panel-title">우리의 성장 일지</h2>${game.lastReport?'<button class="link-button" data-action="last-report">지난달 결과</button>':''}</div><div class="journal-list">${game.journal.slice(0,journalLimit).map(entry=>{const d=E.date({elapsed:entry.month});return `<article class="journal-entry ${entry.tone}"><div class="entry-date">${d.year}<br>${d.month}월</div><div><h3>${esc(entry.title)}</h3><p>${esc(entry.body)}</p></div></article>`}).join('')}</div>${journalLimit<game.journal.length?'<button class="link-button" data-action="more-journal">이전 이야기 더 보기</button>':''}</section>`;
}
  function requirementLabel(r){return r.type==='stat'?C.STATS[r.key].name:r.type==='counter'?'탐험 횟수':{gold:'소지금',trust:'친밀도',condition:'컨디션'}[r.key]||r.key}
  function dreamView(){const possibilities=E.possibilities(game).sort((a,b)=>(b.id===game.dreamId)-(a.id===game.dreamId));return `<p class="small muted" style="margin-bottom:18px">꿈은 일정을 추천하는 길잡이입니다. 열여덟 살의 능력치와 경험이 마지막 진로를 결정해요.</p><div class="ending-grid">${possibilities.map(e=>`<section class="dream-card ${e.id===game.dreamId?'selected':''}"><p class="eyebrow" style="margin-bottom:12px">${e.id===game.dreamId?'지금 마음에 담은 꿈':'A POSSIBLE FUTURE'}</p><h2>${e.title}</h2><p class="tagline">${e.short}</p><div class="progress"><span style="width:${e.progress*100}%"></span></div><div class="requirements">${e.requirements.map(r=>`<span class="requirement ${r.current>=r.min?'met':''}">${requirementLabel(r)} ${number(r.current)} / ${number(r.min)}${r.key==='gold'?'G':''}</span>`).join('')}</div><button class="button small-button" data-action="dream" data-dream="${e.id}" ${e.id===game.dreamId||game.phase!=='planning'?'disabled':''}>${e.id===game.dreamId?'함께 준비하고 있어요':'이 꿈을 준비하기'}</button></section>`).join('')}</div>`}
  function festivalTeaser(){
    const info=E.festivalInfo(game);if(!info.next||game.phase!=='planning')return '';
    return `<section class="festival-teaser"><div><p class="eyebrow">${info.next.year}년 가을제</p><h3>${info.next.monthsUntil===0?'이번 달, 배운 것을 나눌 무대가 열려요':`10월의 무대까지 ${info.next.monthsUntil}개월`}</h3><p>그림·학문·무술·생활 솜씨, 어떤 하루를 준비해 볼까요?</p></div><button class="button small-button" data-action="view" data-view="festival">준비 살펴보기</button></section>`;
}
  function festivalRecordHTML(record){
    const F=window.MakerFestival,d=E.date({elapsed:record.monthIndex}),watching=record.contestId==='watch',contest=F.CONTESTS.find(c=>c.id===record.contestId),rank=F.RANKS.find(r=>r.id===record.rank);
    return `<article class="festival-record festival-rank-${record.rank}"><div class="festival-record-heading"><span class="award-mark" aria-hidden="true">${watching?'燈':rank.mark}</span><div><p class="eyebrow">${d.year}년 · ${d.age}세의 가을</p><h3>${watching?'함께 응원한 하루':`${contest.name} · ${rank.name}`}</h3></div>${watching?'':`<strong class="festival-score">${record.score}<small> / 100점</small></strong>`}</div><p class="festival-purse">${watching?'관람 · 비용 없음':`참가비 −${record.fee}G · ${record.rank==='participant'?'참가 격려금':'상금'} +${record.reward}G`}</p><p class="festival-feedback">${esc(record.feedback)}</p><blockquote>“${esc(record.quote)}”<cite>— ${esc(game.childName)}</cite></blockquote></article>`;
}
  function festivalView(){
    const info=E.festivalInfo(game),records=[...info.results].reverse(),entered=records.filter(r=>r.contestId!=='watch'),awards=entered.filter(r=>['gold','silver','bronze'].includes(r.rank));
    return `<section class="panel festival-intro"><p class="eyebrow">A STAGE FOR THIS YEAR</p><h2 class="panel-title">${info.next?`${info.next.year}년 가을제를 준비해요`:'가을마다 쌓아 온 기억'}</h2><p class="panel-sub">${info.next?info.next.pending?'올해의 초대가 도착했어요. 현재 준비 상태를 보고 한 종목을 골라 주세요.':info.next.monthsUntil===0?'10월의 네 주를 보내면 가을제 초대가 도착합니다. 마지막 주에는 회복할 여유도 챙겨 보세요.':`10월까지 ${info.next.monthsUntil}개월. 일상에서 익힌 것을 또래들과 나누는 무대가 기다립니다.`:'여덟 해의 무대는 마무리되었어요. 함께한 가을을 다시 펼쳐 보세요.'}</p><div class="festival-totals"><span>참가<strong>${entered.length}회</strong></span><span>수상<strong>${awards.length}회</strong></span><span>관람<strong>${records.length-entered.length}회</strong></span></div>${info.next?.pending?'<button class="button primary" data-action="pending-event">올해의 참가 종목 고르기 →</button>':''}</section>${info.next?`<div class="contest-grid">${info.contests.map(c=>`<section class="contest-card ${c.id===info.bestId?'best':''}"><div class="row spread"><span class="contest-mark" aria-hidden="true">${c.mark}</span><span class="contest-tag">${c.id===info.bestId?'지금 가장 준비된 종목':c.ageGroup}</span></div><h3>${c.name}</h3><p class="contest-description">${c.description}</p><div class="contest-abilities"><span>${C.STATS[c.primary].name}<strong>${c.primaryValue}</strong></span><span>${C.STATS[c.secondary].name}<strong>${c.secondaryValue}</strong></span></div><p class="contest-estimate">지금 기준 예상 <strong>${c.min}~${c.max}점</strong></p><div class="progress"><span style="width:${c.min}%"></span></div><p class="contest-rule">${c.ageGroup} · ${C.STATS[c.primary].name} 72% + ${C.STATS[c.secondary].name} 28%</p><button class="button small-button" data-action="festival-practice" data-activity="${c.practice}" ${game.phase==='planning'?'':'disabled'}>${E.activities[c.practice].name} 일정에 넣기</button></section>`).join('')}</div><section class="panel festival-rules"><h3>무대에 서기 전에</h3><p>한 해에 한 종목, 참가비는 ${info.fee}G입니다. 관람은 무료예요. 점수는 나이별 기준과 두 능력치, 컨디션·피로·스트레스를 함께 반영하며 당일에는 ±4점 차이가 날 수 있어요.</p><p>위 예상은 현재 상태 기준입니다. 10월 일정을 마친 뒤 최종 예상과 소지금을 확인하고 참가를 정해요. 입상하지 않아도 두 능력치의 경험과 격려금 10G가 남습니다.</p><div class="festival-prizes">${info.ranks.filter(r=>r.id!=='participant').map(r=>`<span>${r.name} · ${r.min}점 이상<strong>${r.reward}G</strong></span>`).join('')}</div></section>`:''}<section class="panel festival-history"><div class="row spread"><div><h2 class="panel-title">가을제 기록장</h2><p class="panel-sub">상과 심사평, 돌아오는 길의 이야기를 모았어요.</p></div><span class="story-count">${records.length} / 8</span></div>${records.length?records.map(r=>festivalRecordHTML(r)).join(''):'<p class="empty-note">첫 가을의 무대를 기다리고 있어요.<br>참가하든 응원하든, 함께 보낸 하루를 남길 수 있습니다.</p>'}</section>`;
}
  function showFestivalEvent(event){
    const info=E.festivalInfo(game);
    openModal('event',`${modalHeading(event.title,`${info.next.year}년 · ${info.contests[0].ageGroup} · 올해 한 종목`,false)}<p class="festival-invitation">${esc(event.body)}</p><p class="festival-choice-note">10월 일정을 마친 지금의 예상입니다. 참가비 ${info.fee}G · 관람 무료<br>최우수 85점 / 우수 65점 / 장려 45점 이상</p><div class="choice-list">${event.choices.map(choice=>{const c=info.contests.find(c=>c.id===choice.id);return `<button class="event-choice contest-entry" data-action="event-choice" data-choice="${choice.id}" ${choice.affordable?'':'disabled'}><strong>${esc(choice.label)}${c?`<span class="entry-score">${c.min}~${c.max}점 예상</span>`:''}</strong>${c?`<span class="entry-abilities">${C.STATS[c.primary].name} ${c.primaryValue} · ${C.STATS[c.secondary].name} ${c.secondaryValue}</span>`:''}<small>${esc(choice.detail)}${choice.affordable?'':' · 소지금이 부족해요'}</small></button>`}).join('')}</div><p class="footer-note">상금은 성적에 따라 35·70·120G, 입상하지 않으면 격려금 10G를 받아요.<br>심사에는 몸과 마음의 여유도 영향을 줍니다.</p>`);
    const title=document.getElementById('modal-title');title.tabIndex=-1;title.focus({preventScroll:true});modal.scrollTop=0;
}
  function showFestivalResult(record){
    openModal('reaction',`${modalHeading('가을제에서 돌아온 날',`${esc(game.childName)}와 함께 남긴 올해의 기억`)}${festivalRecordHTML(record)}<p class="reaction-effects">${esc(game.lastReport.eventReaction.detail)}</p><p class="footer-note">가을제 화면의 기록장에 보관했습니다.</p><div class="modal-footer"><button class="button primary" data-action="close">다음 달을 준비하기 →</button></div>`);
}
  function showFestivalPractice(activityId){
    if(game.phase!=='planning')return;
    const activity=E.activities[activityId];if(!activity||E.requirement(game,activity))return;
    openModal('festival-practice',`${modalHeading('어느 주에 준비해 볼까요?',`${activity.name}을 이번 달 계획에 넣습니다.`)}<div class="choice-list">${plan.map((id,index)=>`<button class="event-choice" data-action="festival-place" data-week="${index}" data-activity="${activity.id}"><strong>${index+1}주차 · ${id?E.activities[id].name:'비어 있는 일정'}</strong><small>${id?'이 주의 활동을 바꿔요':'이 주에 새로 넣어요'} · ${activity.cost?activity.cost+'G 비용':E.workIncome(game,activity)+'G 예상 수입'}</small></button>`).join('')}</div>`);
}
  function shopEffects(effects){
    const names={condition:'컨디션',fatigue:'피로',stress:'스트레스',trust:'친밀도'};
    return Object.entries(effects).map(([key,n])=>`${names[key]} ${signed(n)}`).join(' · ');
}
  function shopView(){
    const info=E.shopInfo(game),visible=info.items.filter(item=>(shopPane==='catalog'||item.owned>0)&&(shopCategory==='all'||item.category===shopCategory));
    return `<section class="panel shop-intro"><p class="eyebrow">LITTLE THINGS FOR OUR DAYS</p><h2 class="panel-title">오늘을 위한 작은 가게</h2><p class="panel-sub">필요한 것을 골라 보관하고, 알맞은 날에 꺼내 써요.</p><div class="shop-summary"><span>지금 가진 돈<strong>${number(game.gold)}G</strong></span><span>소지품<strong>${info.totalQuantity}개</strong></span><span>이번 달 회복품<strong>${info.remaining.recovery}회 남음</strong></span><span>이번 달 선물<strong>${info.remaining.gift}회 남음</strong></span></div><div class="prepared-tool"><div><span class="eyebrow">준비해 둔 도구</span><h3>${info.equippedTool?info.equippedTool.name:'아직 준비한 도구가 없어요'}</h3><p>${info.equippedTool?esc(E.itemUsePreview(game,info.equippedTool.id).detail):'도구를 하나 준비하면 관련 활동의 성장을 조금 도와줘요.'}</p></div>${info.equippedTool?`<button class="button small-button" data-action="shop-unequip" ${game.phase==='planning'?'':'disabled'}>넣어두기</button>`:''}</div>${game.phase!=='planning'?'<p class="shop-phase-note">지금은 물건을 살펴볼 수 있어요. 진행 중인 이야기를 마무리하면 구매와 사용이 열립니다.</p>':''}</section><div class="shop-pane-tabs" role="group" aria-label="상점과 소지품함"><button class="button ${shopPane==='catalog'?'primary':'ghost'}" data-action="shop-pane" data-pane="catalog" aria-pressed="${shopPane==='catalog'}">물건 사기</button><button class="button ${shopPane==='bag'?'primary':'ghost'}" data-action="shop-pane" data-pane="bag" aria-pressed="${shopPane==='bag'}">소지품함 · ${info.totalQuantity}</button></div><div class="shop-filters" role="group" aria-label="물건 종류">${[['all','모두 보기'],...Object.entries(info.categories)].map(([id,label])=>`<button class="shop-filter ${shopCategory===id?'active':''}" data-action="shop-category" data-category="${id}" aria-pressed="${shopCategory===id}">${label}</button>`).join('')}</div>${visible.length?`<div class="shop-grid">${visible.map(item=>`<article class="shop-card ${item.equipped?'shop-card-prepared':''}" data-shop-item="${item.id}"><div class="row spread"><span class="shop-mark" aria-hidden="true">${item.mark}</span><span class="shop-stock">${item.equipped?'준비 중':item.owned?'보유 '+item.owned+'개':info.categories[item.category]}</span></div>${art('items',item.id,item.name)}<h3>${item.name}</h3><p class="shop-description">${item.description}</p>${item.preview.favorite?'<span class="shop-favorite">취향에 맞는 선물</span>':''}<p class="shop-effect">${esc(item.category==='tool'?item.preview.detail:shopEffects(item.preview.baseEffects))}</p><div class="shop-card-footer">${shopPane==='catalog'?`<strong class="shop-price">${item.price}<small> G</small></strong><button class="button small-button" data-action="shop-detail" data-item="${item.id}">살펴보기</button>`:`<span class="shop-count">${item.owned}개 보관 중</span>${item.category==='tool'?item.equipped?`<button class="button small-button" data-action="shop-unequip" ${game.phase==='planning'?'':'disabled'}>넣어두기</button>`:`<button class="button small-button" data-action="shop-equip" data-item="${item.id}" ${item.preview.canUse?'':'disabled'}>준비하기</button>`:`<button class="button small-button" data-action="shop-use-preview" data-item="${item.id}" ${item.preview.canUse?'':'disabled'}>${item.category==='gift'?'선물 건네기':'사용하기'}</button>`}`}</div>${shopPane==='bag'&&!item.preview.canUse&&!item.equipped?`<p class="shop-item-reason">${esc(item.preview.reason)}</p>`:''}</article>`).join('')}</div>`:`<section class="panel shop-empty"><p class="empty-note">${shopPane==='bag'?'아직 이곳에 보관한 물건이 없어요.<br>가게에서 고른 물건이 소지품함에 담깁니다.':'이 종류의 물건이 아직 없어요.'}</p>${shopPane==='bag'?'<button class="button small-button" data-action="shop-pane" data-pane="catalog">가게 둘러보기</button>':''}</section>`}<section class="panel shop-rules"><h3>작은 물건을 사용하는 방법</h3><p>회복품은 종류를 합쳐 월 2회, 선물은 월 1회 사용할 수 있어요. 간식과 선물은 종류별로 5개까지, 도구는 하나씩 보관합니다. 도구는 한 번에 하나를 준비하고, 맞는 활동을 실제로 마친 최대 2주에 능력치를 1씩 보태요.</p><p>물건은 계획을 세우는 동안 구매·사용할 수 있습니다. 친밀도 90부터는 선물보다 특별한 순간을 함께하며 더 가까워져요.</p></section>${info.lastUse?`<section class="panel shop-memory"><p class="eyebrow">최근 함께 꺼낸 물건</p><h3>${info.items.find(i=>i.id===info.lastUse.itemId).name}</h3><blockquote>“${esc(info.lastUse.quote)}”<cite>— ${esc(game.childName)}</cite></blockquote><p>${esc(info.lastUse.detail)}</p></section>`:''}`;
}
  function showShopItem(id){
    const info=E.shopInfo(game),item=info.items.find(item=>item.id===id);if(!item)return;
    const afterGold=game.gold-item.price,forecast=game.phase==='planning'&&afterGold>=0?E.forecast({...game,gold:afterGold},plan):null;
    openModal('shop-item',`${modalHeading(item.name,info.categories[item.category])}<p class="shop-modal-description">${item.description}</p>${item.preview.favorite?`<p class="shop-favorite">${esc(game.childName)}의 취향에 맞는 선물이에요.</p>`:''}<div class="shop-detail-effects"><span>기본 효과</span><p>${esc(item.category==='tool'?item.preview.detail:shopEffects(item.preview.baseEffects))}</p></div><div class="shop-purchase-summary"><span>한 개 가격<strong>${item.price}G</strong></span><span>보관한 수량<strong>${item.owned} / ${item.category==='tool'?1:info.limits.stack}개</strong></span><span>${afterGold<0?'부족한 돈':'구매 후 소지금'}<strong>${number(Math.abs(afterGold))}G</strong></span></div>${forecast?.complete&&forecast.unaffordableWeeks.length?`<p class="planner-warning">이 물건을 사면 현재 계획의 ${forecast.unaffordableWeeks.join('·')}주차 비용이 부족해요. 구매 후 배움과 일손의 비율을 살펴보세요.</p>`:''}<p class="shop-item-reason">${item.canBuy?'구매한 물건은 소지품함에 보관됩니다. 사용할 때 효과를 확인할 수 있어요.':esc(item.buyReason)}</p><div class="modal-footer">${item.owned>0?item.category==='tool'?item.equipped?`<button class="button" data-action="shop-unequip" ${game.phase==='planning'?'':'disabled'}>넣어두기</button>`:`<button class="button" data-action="shop-equip" data-item="${id}" ${item.preview.canUse?'':'disabled'}>준비하기</button>`:`<button class="button" data-action="shop-use-preview" data-item="${id}" ${item.preview.canUse?'':'disabled'}>${item.category==='gift'?'선물 건네기':'지금 사용하기'}</button>`:''}<button class="button primary" data-action="shop-buy" data-item="${id}" ${item.canBuy?'':'disabled'}>한 개 구매 · ${item.price}G</button></div>`);
}
  function showItemUse(id){
    const item=E.shopInfo(game).items.find(item=>item.id===id);if(!item)return;
    const preview=item.preview;
    openModal('item-use',`${modalHeading(item.name,`${esc(game.childName)}의 하루를 돌보는 시간`)}<p class="shop-modal-description">${item.description}</p>${preview.favorite?'<p class="shop-favorite">취향에 맞아 조금 더 반가워할 선물이에요.</p>':''}<div class="shop-detail-effects"><span>지금 사용하면</span><p>${esc(preview.detail)}</p></div><p class="shop-use-note">소지품 한 개를 사용합니다. ${item.category==='gift'?'이번 달 선물 1회':'이번 달 회복품 사용 1회'}에 포함돼요.</p>${!preview.canUse?`<p class="shop-item-reason">${esc(preview.reason)}</p>`:''}<div class="modal-footer"><button class="button ghost" data-action="close">다음에 꺼내기</button><button class="button primary" data-action="shop-use" data-item="${id}" ${preview.canUse?'':'disabled'}>${item.category==='gift'?'마음을 담아 건네기':'함께 사용하기'}</button></div>`);
}
  function showItemReply(item,result){
    const info=E.shopInfo(game);
    openModal('item-result',`${modalHeading(item.category==='gift'?'마음을 전한 오후':'잠깐 쉬어 가는 시간',`${esc(game.childName)}의 답변 · ${item.name}`)}<p class="care-quote">“${esc(result.quote)}”</p><p class="reaction-effects">${esc(result.detail)}</p><p class="shop-use-note">남은 수량 ${info.items.find(i=>i.id===item.id).owned}개 · 이번 달 ${item.category==='gift'?'선물 '+info.remaining.gift:'회복품 '+info.remaining.recovery}회 남음</p><div class="modal-footer"><button class="button primary" data-action="close">소지품함으로 돌아가기</button></div>`);
}
  function showWardrobe(){
    const d=E.date(game),look=A.resolve(M,{characterId:game.characterId,originId:game.originId,age:d.age,season:E.season(game)},selectedOutfit),choices=A.choices(M,game.characterId,d.age);
    openModal('wardrobe',`${modalHeading(`${esc(game.childName)}의 옷장`,`${look.age}세의 그림 · ${C.ORIGINS[game.originId].room}`)}<div class="wardrobe-layout"><div class="wardrobe-stage"><div id="wardrobe-preview">${portrait(true)}</div><button class="link-button" data-action="wardrobe-room" aria-pressed="${wardrobeRoomOnly}">${wardrobeRoomOnly?'캐릭터와 함께 보기':'방만 살펴보기'}</button></div><section class="wardrobe-controls"><p class="eyebrow">TODAY'S OUTFIT</p><h3 id="current-outfit-name">${look.label}</h3><p class="wardrobe-note">좋아하는 옷을 골라 보세요. 의상 선택은 능력치나 돈에 영향을 주지 않습니다.</p><div class="wardrobe-options" role="group" aria-label="의상 선택">${choices.map(c=>`<button class="outfit-option ${selectedOutfit===c.id?'selected':''}" data-action="outfit" data-outfit="${c.id}" aria-pressed="${selectedOutfit===c.id}" ${c.available?'':'disabled'}>${c.id==='auto'?`<span class="outfit-auto" aria-hidden="true">四季</span>`:c.source?`<img class="outfit-thumb" src="${c.source}" alt="" loading="lazy">`:'<span class="outfit-unavailable" aria-hidden="true">—</span>'}<strong>${c.label}</strong>${!c.available?`<small>${c.firstAge?c.firstAge+'세부터':'준비 중'}</small>`:''}</button>`).join('')}</div><p class="wardrobe-note">계절에 맞게를 고르면 여름과 겨울에 옷이 자동으로 바뀝니다. 고른 옷은 저장함과 내보낸 이야기 파일에도 남아요.</p><div class="wardrobe-links"><a id="wardrobe-character-link" href="${look.source}" target="_blank" rel="noopener">캐릭터 그림 크게 보기</a><a href="${look.roomSource}" target="_blank" rel="noopener">방 그림 크게 보기</a></div></section></div><div class="modal-footer"><button class="button primary" data-action="close">이 모습으로 함께하기</button></div>`);
}
  function updateWardrobe(){
    if(!modal.open||modal.dataset.kind!=='wardrobe')return;
    const d=E.date(game),look=A.resolve(M,{characterId:game.characterId,originId:game.originId,age:d.age,season:E.season(game)},selectedOutfit);
    document.getElementById('wardrobe-preview').innerHTML=portrait(true);document.getElementById('current-outfit-name').textContent=look.label;document.getElementById('wardrobe-character-link').href=look.source;
    modal.querySelectorAll('.outfit-option').forEach(button=>{const selected=button.dataset.outfit===selectedOutfit;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});
    const toggle=modal.querySelector('[data-action="wardrobe-room"]');toggle.textContent=wardrobeRoomOnly?'캐릭터와 함께 보기':'방만 살펴보기';toggle.setAttribute('aria-pressed',String(wardrobeRoomOnly));
}
  function art(group,id,alt){const path=window.MakerScenes?.[group]?.[id];return typeof path==='string'&&/^scenes\/[a-z0-9_/-]+\.(?:webp|png|jpe?g)$/i.test(path)?'<img class="scene-art" data-media="scene" src="'+esc(mediaURL(path))+'" alt="'+esc(alt)+'" decoding="async">':''}
  function render(){
    if(!game){landing();return}
    const content=view==='plan'?planner():view==='status'?G.status(game,true):view==='outing'?G.outing(art):view==='journal'?journalView():view==='festival'?festivalView():view==='shop'?art('locations','shop','상점')+shopView():view==='dreams'?dreamView():'';
    app.innerHTML=G.render({game,plan,view,portrait,meter,content});
  }
  function openModal(kind,html){if(modal.open)modal.close();modal.dataset.kind=kind;modal.innerHTML=html;modal.showModal()}
  function modalHeading(title,subtitle='',close=true){return `<div class="modal-heading"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${close?'<button class="close-button" data-action="close" aria-label="닫기">×</button>':''}</div>`}
  function showSetup(){openModal('setup',`${modalHeading('우리의 첫 번째 봄','함께할 아이와 이야기가 시작될 집을 골라 주세요.')}<form id="setup-form"><div class="character-options">${Object.entries(C.CHARACTERS).map(([id,c],index)=>`<label class="character-option"><input type="radio" name="character" value="${id}" ${index===0?'checked':''}><img class="character-option-image" src="${mediaURL(M.portraits[id][10].base)}" alt="10세 ${c.name}"><span><strong>${c.name}</strong><small>${c.description}</small></span></label>`).join('')}</div><div class="form-row"><label><span class="form-label">아이의 이름</span><input class="text-input" name="childName" maxlength="16" value="시엘" required autocomplete="off"></label><label><span class="form-label">보호자의 이름</span><input class="text-input" name="guardianName" maxlength="16" value="보호자" required autocomplete="off"></label></div><span class="form-label">이야기가 시작되는 집</span><div class="origin-options">${Object.entries(C.ORIGINS).map(([id,o],i)=>`<label class="origin-option"><input type="radio" name="origin" value="${id}" ${i===0?'checked':''}><img class="origin-option-image" src="${mediaURL(M.rooms[id])}" alt="${o.room}" loading="lazy"><strong>${o.name}의 집</strong><small>${o.gold}G로 시작</small></label>`).join('')}</div><label><span class="form-label">마음에 담아 둘 작은 꿈</span><select class="text-input" name="dream">${C.ENDINGS.filter(e=>!e.fallback).map(e=>`<option value="${e.id}" ${e.id==='artist'?'selected':''}>${e.title}</option>`).join('')}</select></label><p id="setup-summary" class="setup-summary"></p><div class="modal-footer"><button type="button" class="button ghost" data-action="close">돌아가기</button><button id="begin-story" class="button primary" type="submit">이 봄을 함께 시작하기 →</button></div></form>`);updateSetup()}
  function updateSetup(){
    const form=document.getElementById('setup-form');if(!form)return;
    const data=new FormData(form),origin=C.ORIGINS[data.get('origin')];
    document.getElementById('setup-summary').textContent=`${origin.description}. ${origin.gold}G와 함께 시작합니다. 월 지원금은 ${origin.allowance}G이며 처음 세 달은 정착 지원 15G가 더해져요. 생활비는 매달 18G부터 시작해 나이에 따라 늘어납니다. 열 살부터 열여덟 살까지, 96개월을 함께 보냅니다.`;
}
  function showActivities(week){pickerWeek=week;const existing=E.activities[plan[week]];pickerCategory=existing?.category||'study';openModal('activity',`${modalHeading(`${week+1}주차의 시간을 골라 주세요`,'비용과 수입은 한 주 기준입니다. 실제 성장은 컨디션에 따라 달라져요.')}<div class="activity-tabs" role="group" aria-label="활동 종류">${Object.entries(C.CATEGORIES).map(([id,name])=>`<button class="activity-tab ${id===pickerCategory?'active':''}" data-action="activity-category" data-category="${id}">${name}</button>`).join('')}</div><div id="activity-list" class="activity-list"></div>`);renderActivities()}
  function renderActivities(){document.querySelectorAll('.activity-tab').forEach(button=>button.classList.toggle('active',button.dataset.category===pickerCategory));document.getElementById('activity-list').innerHTML=C.ACTIVITIES.filter(a=>a.category===pickerCategory).map(a=>{const locked=E.requirement(game,a);return `<button class="activity-choice" data-action="choose-activity" data-activity="${a.id}" ${locked?'disabled':''}>${art('activities',a.id,a.name)}<span class="mark" aria-hidden="true">${a.mark}</span><span><h3>${a.name}</h3><p>${a.description}</p><p class="effects">${Object.entries(a.gains).map(([key,n])=>`${C.STATS[key].name} +${n}`).join(' · ')}${Object.keys(a.gains).length?'<br>':''}피로 ${signed(a.fatigue)} · 스트레스 ${signed(a.stress)}</p><p class="price">${locked?esc(locked):a.cost?`${a.cost}G 비용`:a.income?`${E.workIncome(game,a)}G 수입`:'비용 없음'}</p></span></button>`}).join('')}
  function showCare(){
    if(game.careMonth===game.elapsed)return;
    const talk=E.careEffects(game,'talk'),treat=E.careEffects(game,'treat');
    openModal('care',`${modalHeading('잠깐, 함께 앉아 볼까요?',`${esc(game.childName)}와 마음을 나누는 시간입니다.`)}<p class="care-quote">“${esc(E.characterVoice(game))}”</p><div class="choice-list"><button class="event-choice" data-action="do-care" data-care="talk"><strong>마주 앉아 이야기를 듣는다</strong><small>비용 없음 · 친밀도 +${talk.trust} · 스트레스 -6</small></button><button class="event-choice" data-action="do-care" data-care="treat" ${game.gold<15?'disabled':''}><strong>좋아하는 간식을 함께 먹는다</strong><small>15G · 친밀도 +${treat.trust} · 피로 -6 · 스트레스 -10</small></button></div><p class="footer-note">친밀도가 높아지면 일상의 대화로 오르는 폭이 작아져요.<br>친밀도 90부터는 특별한 순간을 함께하며 더 가까워집니다.</p>`);
}
  function gainsHTML(gains){return `<div class="gains">${Object.entries(gains).filter(([,n])=>n>0).map(([key,n])=>`<span class="gain-chip">${C.STATS[key].name} +${n}</span>`).join('')}</div>`}
  function showReport(replay=false){
    const r=game.lastReport;if(!r)return;
    const allGains=Object.fromEntries(KEYS.map(key=>[key,r.after.stats[key]-r.before.stats[key]]));
    openModal('report',`${modalHeading(`${r.date.month}월, 이렇게 보냈어요`,`${r.date.year}년 · ${esc(game.childName)}의 ${r.date.age}세 이야기`,replay)}<div class="report-summary"><span>배움과 휴식에<strong>−${r.expenses}G</strong></span><span>일손과 발견으로<strong>+${r.income}G</strong></span><span>월 지원금<strong>+${r.allowance}G</strong></span><span>생활비<strong>−${r.livingCost||0}G</strong></span></div>${r.starterGrant?'<p class="budget-note">월 지원금에 정착 지원 15G가 포함되어 있어요.</p>':''}${gainsHTML(allGains)}${r.weeks.map(w=>`<article class="report-week"><span class="number">0${w.week}</span><div>${art('activities',w.activityId,E.activities[w.activityId].name)}<h3>${E.activities[w.activityId].name}${w.activityId!==w.plannedId?' · 회복 일정':''}</h3>${gainsHTML(w.gains)}${w.income?`<p>받은 주급${w.activityId==='explore'?'과 발견 수입':''} · ${w.income}G</p>`:''}${w.note?`<p>${esc(w.note)}</p>`:''}${w.toolBonus?`<p class="report-tool-bonus">준비 도구 · ${esc(E.shopInfo(game).items.find(i=>i.id===w.toolBonus.itemId).name)} · ${C.STATS[w.toolBonus.stat].name} +${w.toolBonus.amount} · 위 성장량에 포함</p>`:''}${w.reaction?`<p class="week-reaction">“${esc(w.reaction)}”</p>`:''}${w.efficiency<100?`<p>집중도 ${w.efficiency}% · 휴식으로 몸과 마음의 여유를 챙겨 주세요.</p>`:''}</div></article>`).join('')}${r.choiceLabel?`<p class="small muted" style="margin-top:17px">함께 고른 이야기: ${esc(r.choiceLabel)}</p>`:''}${game.festivalResults?.find(f=>f.monthIndex===r.monthIndex)?festivalRecordHTML(game.festivalResults.find(f=>f.monthIndex===r.monthIndex)):''}${r.eventReaction&&!game.festivalResults?.some(f=>f.monthIndex===r.monthIndex)?`<blockquote class="report-reaction">“${esc(r.eventReaction.quote)}”</blockquote>`:''}<div class="modal-footer"><button class="button primary" data-action="${replay?'close':'after-report'}">${replay?'일지로 돌아가기':game.pendingEvent?'이야기 이어보기 →':game.phase==='ending'?'열여덟 살의 이야기 →':'다음 달을 준비하기 →'}</button></div>`);
}
  function showEvent(){
    const event=E.pendingEvent(game);if(!event)return;if(event.id==='harvest'){showFestivalEvent(event);return}
    openModal('event',`${modalHeading(event.title,event.character?`${esc(game.childName)}의 성장 에피소드 ${event.episode} / 12 · ${esc(event.chapter)}`:'어떤 마음으로 이 시간을 보내면 좋을까요?',false)}${art('events',event.id,event.title)}<p class="event-body">${esc(event.body)}</p><div class="choice-list">${event.choices.map(choice=>`<button class="event-choice" data-action="event-choice" data-choice="${choice.id}" ${choice.affordable?'':'disabled'}><strong>${esc(choice.label)}</strong><small>${esc(choice.detail)}${choice.affordable?'':' · 소지금이 부족해요'}</small></button>`).join('')}</div><p class="footer-note">선택한 이야기는 성장 일지에 남습니다.</p>`);
}
  function showReaction(){
    const reaction=game.lastReport?.eventReaction;if(!reaction)return;const festival=game.festivalResults?.find(r=>r.monthIndex===game.lastReport.monthIndex);if(festival){showFestivalResult(festival);return}
    openModal('reaction',`${modalHeading(reaction.title,esc(game.childName)+'의 답변')}<p class="care-quote">“${esc(reaction.quote)}”</p><p class="small muted">${esc(game.lastReport.choiceLabel)}</p><p class="reaction-effects">${esc(reaction.detail)}</p><div class="modal-footer"><button class="button primary" data-action="close">다음 달을 준비하기 →</button></div>`);
  }
  function showEnding(){if(!game.endingId)return;rememberEnding();const ending=E.endings[game.endingId];openModal('ending',`${modalHeading('여덟 번의 봄을 지나')}<div class="ending-top"><span class="star" aria-hidden="true">✧</span><p class="eyebrow" style="margin-top:15px">THE NEXT CHAPTER</p><h2>${ending.title}</h2><p>${ending.description}</p></div>${art('endings',ending.id,ending.title)}<div class="ending-letter">${esc(ending.letter)}<footer>— 열여덟 살의 ${esc(game.childName)}가,<br>${esc(game.guardianName)}에게</footer></div><p class="ending-totals">96개월의 시간 · ${number(game.counters.weeksStudied)}주의 배움 · ${number(game.counters.explorations)}번의 탐험<br>가을제 ${game.festivalResults?.filter(r=>r.contestId!=='watch').length||0}회 참가 · ${game.festivalResults?.filter(r=>['gold','silver','bronze'].includes(r.rank)).length||0}회 수상<br>만난 결말 ${collection().length} / ${C.ENDINGS.length}</p><div class="modal-footer"><button class="button" data-action="export">이야기 파일로 보관</button><button class="button primary" data-action="close">성장 일지로 돌아가기</button></div>`)}
  function showSaves(){const auto=saveInfo(read(AUTO));openModal('saves',`${modalHeading('이야기를 보관하는 서랍','자동저장과 별도로 세 개의 이야기를 보관할 수 있습니다.')}<p class="save-section-title">자동으로 남긴 이야기</p><div class="save-slot"><div><strong>${auto&&!auto.invalid?`${esc(auto.name)} · ${auto.age}세`:'자동저장된 이야기가 없어요'}</strong><small>${auto&&!auto.invalid?auto.date+' · '+(auto.ending?'완성된 이야기':'이어 쓸 이야기'):auto?.invalid?'저장 내용을 읽을 수 없습니다.':''}</small></div><button class="button small-button" data-action="continue" ${!auto||auto.invalid?'disabled':''}>이어가기</button></div><p class="save-section-title">따로 보관하는 이야기</p>${[0,1,2].map(index=>{const saved=saveInfo(read('slot-'+index));return `<div class="save-slot"><div><strong>${index+1}번째 서랍${saved&&!saved.invalid?' · '+esc(saved.name):''}</strong><small>${saved&&!saved.invalid?`${saved.age}세 · ${saved.date}`:saved?.invalid?'파일을 읽을 수 없어요':'아직 비어 있어요'}</small></div><div class="row"><button class="button small-button" data-action="save-slot" data-slot="${index}" ${game?'':'disabled'}>보관</button><button class="button small-button ghost" data-action="load-slot" data-slot="${index}" ${!saved||saved.invalid?'disabled':''}>불러오기</button></div></div>`}).join('')}<div class="save-tools"><button class="button small-button" data-action="export" ${game?'':'disabled'}>파일로 내보내기</button><label class="button small-button file-label">저장 파일 가져오기<input id="import-save" type="file" accept=".json,application/json" hidden></label><button class="button small-button ghost" data-action="collection">엔딩 모아보기</button><button class="button small-button ghost" data-action="new">새 이야기</button></div><p class="footer-note">다른 브라우저나 기기로 옮기려면 저장 파일을 내보내 주세요.</p>`)}
  function showCollection(){const unlocked=collection();openModal('collection',`${modalHeading('우리가 만난 결말',`${unlocked.length} / ${C.ENDINGS.length}개의 이야기를 만났습니다.`)}<div class="choice-list">${C.ENDINGS.map(e=>`<div class="event-choice"><strong>${unlocked.includes(e.id)?e.title:'아직 만나지 않은 이야기'}</strong><small>${unlocked.includes(e.id)?e.short:'함께 쌓은 하루가 새로운 길을 열어 줄 거예요.'}</small></div>`).join('')}</div>`)}
  function showHelp(){openModal('help',`${modalHeading('작은 하루를 쌓는 방법','하나의 정답보다, 함께 고른 시간에 의미가 있어요.')}<div class="help-steps">${[['한 달의 네 시간을 정해요','1주차부터 4주차까지 활동을 골라 주세요. 처음에는 추천 일정을 사용해도 좋습니다. 배움에는 비용이 들고, 일손 돕기로 돈을 벌 수 있어요. 월 지원금은 45G이며 처음 세 달은 15G를 더 받아요. 생활비는 10·12·14·16세부터 각각 월 18·24·30·36G입니다. 일손 경험 8주와 24주에 주급이 오르지만, 피로가 쌓이면 주급도 줄어들어요.'],['몸과 마음에 귀를 기울여요','피로와 스트레스가 높으면 배움의 효율이 낮아집니다. 컨디션이 크게 떨어지면 자동으로 쉬게 됩니다. 한 달에 한 번 대화하는 시간도 챙겨 주세요.'],['만나는 이야기에서 선택해요','월간 결과를 본 뒤 선택 이벤트가 이어질 수 있습니다. 시엘과 발레리아에게는 각각 12편의 성장 에피소드가 있습니다. 앞선 선택에 따라 다음 장면의 대사가 달라져요. 선택과 아이의 답변은 성장 일지의 에피소드 모음에 남아요. 선택하지 않은 이벤트는 불러와도 계속 기다립니다.'],['필요한 물건을 골라요','상점에서 회복품과 도구, 선물을 사서 소지품함에 보관할 수 있어요. 회복품은 월 2회, 선물은 월 1회 사용합니다. 도구는 하나를 준비하면 관련 활동을 마친 최대 2주에 능력치가 1씩 더 자라요. 물건을 살 때는 남는 돈과 이번 달 일정 비용도 함께 살펴보세요.'],['가을제에서 한 해를 돌아봐요','매년 10월의 일정을 마치면 가을제에 초대됩니다. 가을제 화면에서 네 종목의 예상 성적과 연습할 활동을 볼 수 있어요. 한 종목에 20G로 참가하거나 무료로 관람할 수 있습니다. 성적은 나이별 기준과 능력치, 몸 상태로 정해지고 상금과 심사평은 가을제 기록장에 남습니다.'],['열여덟 살의 다음 장을 만나요','96개월이 지나면 능력치와 경험에 따라 진로가 결정됩니다. 꿈과 진로 화면에서 준비 상태를 볼 수 있어요. 진행은 자동저장되며, 저장함에서 따로 보관하거나 파일로 옮길 수 있습니다.']].map(([title,body])=>`<div class="help-step"><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div>`)}
  function exportSave(){if(!game)return;const blob=new Blob([payload()],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`별이-자라는-집-${game.childName.replace(/[\\/:*?"<>|]/g,'')}-${game.elapsed}개월.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('이야기를 저장 파일로 내보냈어요.')}
  async function importSave(file){if(!file)return;if(file.size>2000000){toast('저장 파일이 너무 큽니다.',true);return}try{const raw=await file.text();decode(raw);load(raw);toast('보관한 이야기를 불러왔어요.')}catch(error){toast(error.message,true)}}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;
    try{
      if(action==='close'){modal.close();return}
      if(action==='new'){if((game?.elapsed>0&&game.phase!=='ending')||(!game&&saveInfo(read(AUTO))&&!saveInfo(read(AUTO)).invalid)){if(!window.confirm('새 이야기를 시작하면 자동저장 내용이 바뀝니다. 보관할 내용은 저장함에 먼저 남겨 주세요. 새 이야기를 시작할까요?'))return}showSetup();return}
      if(action==='continue'){const raw=read(AUTO);if(raw)load(raw);return}
      if(action==='help'){showHelp();return}
      if(action==='saves'){showSaves();return}
      if(action==='collection'){showCollection();return}
      if(action==='export'){exportSave();return}
      if(action==='save-slot'){if(write('slot-'+Number(button.dataset.slot),payload())){showSaves();toast('이야기를 서랍에 보관했어요.')}return}
      if(action==='load-slot'){const raw=read('slot-'+Number(button.dataset.slot));if(raw){load(raw);toast('보관한 이야기를 불러왔어요.')}return}
      if(!game)return;
      if(action==='wardrobe'){wardrobeRoomOnly=false;showWardrobe();return}
      if(action==='wardrobe-room'){wardrobeRoomOnly=!wardrobeRoomOnly;updateWardrobe();return}
      if(action==='outfit'){const id=button.dataset.outfit,age=E.date(game).age;if(!A.choices(M,game.characterId,age).some(c=>c.id===id&&c.available))return;selectedOutfit=id;wardrobeRoomOnly=false;persist();render();updateWardrobe();return}
      if(action==='view'){view=button.dataset.view;render();document.querySelector('.window-bar button')?.focus();return}
      if(action==='destination'){
        const dest=button.dataset.destination;
        if(dest==='shop'||dest==='festival'){view=dest;render();return}
        if(game.phase!=='planning'){toast('진행 중인 이야기를 먼저 마무리해 주세요.');return}
        view='plan';render();showActivities(Math.max(0,plan.findIndex(id=>!id)));pickerCategory=dest==='education'?'study':dest==='adventure'?'adventure':'work';renderActivities();return;
      }
      if(action==='shop-pane'){shopPane=button.dataset.pane==='bag'?'bag':'catalog';shopCategory='all';render();return}
      if(action==='shop-category'){shopCategory=button.dataset.category;render();return}
      if(action==='shop-detail'){showShopItem(button.dataset.item);return}
      if(action==='shop-buy'){const id=button.dataset.item;game=E.buyItem(game,id);persist();render();showShopItem(id);toast('소지품함에 한 개 보관했어요.');return}
      if(action==='shop-use-preview'){showItemUse(button.dataset.item);return}
      if(action==='shop-use'){const id=button.dataset.item,item=E.shopInfo(game).items.find(i=>i.id===id),result=E.useItem(game,id);game=result.game;view='shop';shopPane='bag';persist();render();showItemReply(item,result);return}
      if(action==='shop-equip'||action==='shop-unequip'){game=E.equipTool(game,action==='shop-unequip'?null:button.dataset.item);modal.close();persist();render();toast(action==='shop-unequip'?'도구를 소지품함에 넣었어요.':'이번 달 배움을 도울 도구를 준비했어요.');return}
      if(action==='festival-practice'){showFestivalPractice(button.dataset.activity);return}
      if(action==='festival-place'){if(game.phase!=='planning')return;const week=Number(button.dataset.week),id=button.dataset.activity;if(!Number.isInteger(week)||week<0||week>3||E.requirement(game,id))return;plan[week]=id;view='plan';modal.close();persist();render();toast(`${week+1}주차에 ${E.activities[id].name}을 넣었어요.`);return}
      if(action==='pick-week'){if(game.phase==='planning')showActivities(Number(button.dataset.week));return}
      if(action==='activity-category'){pickerCategory=button.dataset.category;renderActivities();return}
      if(action==='choose-activity'){const id=button.dataset.activity;if(E.requirement(game,id))return;plan[pickerWeek]=id;modal.close();persist();render();document.querySelector(`[data-week="${pickerWeek}"]`)?.focus();return}
      if(action==='recommend'){plan=E.recommend(game);persist();render();toast('지금의 꿈과 몸 상태를 생각해 일정을 골랐어요.');return}
      if(action==='repeat'){plan=[...game.lastPlan];persist();render();return}
      if(action==='advance'){view='home';game=E.advanceMonth(game,plan);plan=[null,null,null,null];persist();render();showReport();return}
      if(action==='after-report'){modal.close();if(game.phase==='event')showEvent();else if(game.phase==='ending')showEnding();return}
      if(action==='pending-event'){showEvent();return}
      if(action==='event-choice'){game=E.resolveEvent(game,button.dataset.choice);modal.close();persist();render();if(game.phase==='ending')showEnding();else if(game.lastReport?.eventReaction)showReaction();else toast('함께 고른 이야기가 일지에 남았어요.');return}
      if(action==='care'){showCare();return}
      if(action==='do-care'){const result=E.care(game,button.dataset.care);game=result.game;modal.close();persist();render();toast(`${game.childName}: “${result.quote}”`);return}
      if(action==='dream'){game=E.setDream(game,button.dataset.dream);persist();render();toast('함께 준비할 꿈을 바꿨어요.');return}
      if(action==='more-journal'){journalLimit+=12;render();return}
      if(action==='last-report'){showReport(true);return}
      if(action==='ending'){showEnding();return}
    }catch(error){toast(error.message||'진행 내용을 다시 확인해 주세요.',true)}
  });
  document.addEventListener('submit',event=>{if(event.target.id!=='setup-form')return;event.preventDefault();try{const data=new FormData(event.target);game=E.createGame({characterId:data.get('character'),originId:data.get('origin'),childName:data.get('childName'),guardianName:data.get('guardianName'),dreamId:data.get('dream')});plan=[null,null,null,null];selectedOutfit='auto';view='home';chartStat=game.characterId==='ciel'?'art':'combat';modal.close();persist();render();toast('우리의 첫 번째 봄이 시작됐어요.')}catch(error){toast(error.message,true)}});
  document.addEventListener('change',event=>{
    if(event.target.closest('#setup-form')){if(event.target.name==='character'){const form=document.getElementById('setup-form'),id=event.target.value;if(['시엘','발레리아',''].includes(form.elements.childName.value))form.elements.childName.value=C.CHARACTERS[id].name;form.elements.dream.value=C.CHARACTERS[id].dream}updateSetup()}
    if(event.target.id==='chart-stat'){chartStat=event.target.value;render()}
    if(event.target.id==='import-save')importSave(event.target.files?.[0]);
  });
  document.addEventListener('error',event=>{const image=event.target;if(image.tagName==='IMG'&&image.dataset.media){if(image.dataset.media==='child'&&image.dataset.fallback&&image.getAttribute('src')!==image.dataset.fallback){image.src=image.dataset.fallback;return}image.hidden=true;if(image.dataset.media==='child'){const placeholder=image.closest('.portrait')?.querySelector('.portrait-placeholder');if(placeholder)placeholder.hidden=false}}},true);
  modal.addEventListener('cancel',event=>{if(['event','report'].includes(modal.dataset.kind)&&!modal.querySelector('[data-action="close"]'))event.preventDefault()});
  window.addEventListener('starlight:before-update',event=>{if(game){persist();event.detail.saved=saveOK}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.open&&game&&view!=='home'){view='home';render()}});
  render();
})();
